local BrandyDistiller = {}
local PRODUCTS = {
    apple_brandy = { name = "Jabolčno žganje", appleCost = 4, fuelCost = 1, time = 4, cost = 50, alcoholContent = 30, happiness = 3, description = "Jabolčno žganje za kmete." },
    grape_brandy = { name = "Grozdno žganje", grapeCost = 4, fuelCost = 1, time = 5, cost = 90, alcoholContent = 35, happiness = 4, prestige = 2, description = "Grozdno žganje za trgovce." },
    aged_brandy = { name = "Starano žganje", grapeCost = 5, oakCost = 1, fuelCost = 2, time = 8, cost = 220, alcoholContent = 42, happiness = 6, prestige = 5, description = "Starano žganje v hrastovem sodu." },
    spiced_brandy = { name = "Začinjeno žganje", grapeCost = 5, spiceCost = 1, oakCost = 1, fuelCost = 2, time = 10, cost = 480, alcoholContent = 45, happiness = 8, prestige = 10, description = "Začinjeno žganje z redkimi začimbami." },
    silver_distilled_brandy = { name = "Srebrno destilirano žganje", grapeCost = 6, silverCost = 1, oakCost = 1, spiceCost = 1, fuelCost = 2, time = 13, cost = 950, alcoholContent = 50, happiness = 11, prestige = 18, description = "Srebrno destilirano žganje za plemiče." },
    royal_grand_brandy = { name = "Kraljevski veliki žganje", grapeCost = 10, goldCost = 1, silverCost = 1, jewelCost = 1, oakCost = 2, spiceCost = 2, fuelCost = 3, time = 18, cost = 2200, alcoholContent = 60, happiness = 20, prestige = 45, description = "Veliko kraljevsko žganje z zlatom in dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Žganjearska delavnica", cost = { gold = 350, wood = 150, stone = 250 }, upkeep = 9, qualityBonus = 5 },
    distillery = { name = "Destilarna", cost = { gold = 1200, wood = 280, stone = 500, copper = 10 }, upkeep = 30, qualityBonus = 18 },
    aging_cellar = { name = "Starilni sklep", cost = { gold = 2800, wood = 400, stone = 800, silver = 40, oak = 10 }, upkeep = 70, qualityBonus = 30 },
    royal_brandy_atelier = { name = "Kraljevski atelje žganja", cost = { gold = 11000, wood = 700, stone = 1300, gold = 80, jewel = 25 }, upkeep = 220, qualityBonus = 55, prestigeBonus = 45 },
}
BrandyDistiller.grapeStock = 18; BrandyDistiller.appleStock = 14; BrandyDistiller.oakStock = 12; BrandyDistiller.spiceStock = 10; BrandyDistiller.fuelStock = 14; BrandyDistiller.silverStock = 8; BrandyDistiller.goldStock = 6; BrandyDistiller.jewelStock = 6
BrandyDistiller.productStock = {}; BrandyDistiller.buildings = {}; BrandyDistiller.maker = nil; BrandyDistiller.activeMaking = {}; BrandyDistiller.totalProducts = 0; BrandyDistiller.dayTimer = 0
function BrandyDistiller.init() BrandyDistiller.grapeStock=18; BrandyDistiller.appleStock=14; BrandyDistiller.oakStock=12; BrandyDistiller.spiceStock=10; BrandyDistiller.fuelStock=14; BrandyDistiller.silverStock=8; BrandyDistiller.goldStock=6; BrandyDistiller.jewelStock=6; BrandyDistiller.productStock={}; BrandyDistiller.buildings={}; BrandyDistiller.maker=nil; BrandyDistiller.activeMaking={}; BrandyDistiller.totalProducts=0; BrandyDistiller.dayTimer=0; print("[BrandyDistiller] Royal Brandy Distiller System initialized (6 products, 4 buildings)") end
function BrandyDistiller.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; BrandyDistiller.maker={name=n or ("Žganjear "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Žganjear najet: %s (spretnost: %d)",BrandyDistiller.maker.name,s),"success") end; return true end
function BrandyDistiller.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function BrandyDistiller.build(id) local ok,e=BrandyDistiller.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(BrandyDistiller.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function BrandyDistiller.getQualityBonus() local b=0; for _,bd in ipairs(BrandyDistiller.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function BrandyDistiller.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.grapeCost and BrandyDistiller.grapeStock<(d.grapeCost or 0) then return false,"Premalo grozdja" end; if d.appleCost and BrandyDistiller.appleStock<(d.appleCost or 0) then return false,"Premalo jabolk" end; if d.oakCost and BrandyDistiller.oakStock<(d.oakCost or 0) then return false,"Premalo hrasta" end; if d.spiceCost and BrandyDistiller.spiceStock<(d.spiceCost or 0) then return false,"Premalo začimb" end; if d.fuelCost and BrandyDistiller.fuelStock<(d.fuelCost or 0) then return false,"Premalo goriva" end; if d.silverCost and BrandyDistiller.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and BrandyDistiller.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and BrandyDistiller.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if #BrandyDistiller.buildings==0 then return false,"Potrebna delavnica" end; if not BrandyDistiller.maker then return false,"Potreben žganjear" end; return true end
function BrandyDistiller.make(pt,qty) qty=qty or 5; local ok,e=BrandyDistiller.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.grapeCost then BrandyDistiller.grapeStock=BrandyDistiller.grapeStock-d.grapeCost*qty end; if d.appleCost then BrandyDistiller.appleStock=BrandyDistiller.appleStock-d.appleCost*qty end; if d.oakCost then BrandyDistiller.oakStock=BrandyDistiller.oakStock-d.oakCost*qty end; if d.spiceCost then BrandyDistiller.spiceStock=BrandyDistiller.spiceStock-d.spiceCost*qty end; if d.fuelCost then BrandyDistiller.fuelStock=BrandyDistiller.fuelStock-d.fuelCost*qty end; if d.silverCost then BrandyDistiller.silverStock=BrandyDistiller.silverStock-d.silverCost*qty end; if d.goldCost then BrandyDistiller.goldStock=BrandyDistiller.goldStock-d.goldCost*qty end; if d.jewelCost then BrandyDistiller.jewelStock=BrandyDistiller.jewelStock-d.jewelCost*qty end; local t=d.time; if BrandyDistiller.maker then t=math.max(1,t-math.floor(BrandyDistiller.maker.skill/12)) end; table.insert(BrandyDistiller.activeMaking,{id="brandy_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,alcoholContent=d.alcoholContent or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function BrandyDistiller.completeMaking(m) local q=1.0+(BrandyDistiller.getQualityBonus()/100); if BrandyDistiller.maker then q=q+(BrandyDistiller.maker.skill/150) end; q=math.min(2.5,q); BrandyDistiller.productStock[m.productType]=(BrandyDistiller.productStock[m.productType] or 0)+m.quantity; BrandyDistiller.totalProducts=BrandyDistiller.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if BrandyDistiller.maker then BrandyDistiller.maker.itemsMade=BrandyDistiller.maker.itemsMade+m.quantity; if math.random()<0.25 then BrandyDistiller.maker.skill=math.min(100,BrandyDistiller.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Žganje izdelano: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"brandy.completed",{productName=m.productName,alcoholContent=m.alcoholContent,happiness=m.happiness}) end end
function BrandyDistiller.update(dt) if not _G.state then return end; BrandyDistiller.dayTimer=BrandyDistiller.dayTimer+dt; if BrandyDistiller.dayTimer>=30 then BrandyDistiller.dayTimer=0; for i=#BrandyDistiller.activeMaking,1,-1 do local m=BrandyDistiller.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then BrandyDistiller.completeMaking(m); table.remove(BrandyDistiller.activeMaking,i) end end; local tu=0; for _,bd in ipairs(BrandyDistiller.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if BrandyDistiller.maker then tu=tu+18 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function BrandyDistiller.getStats() return {grapeStock=BrandyDistiller.grapeStock,appleStock=BrandyDistiller.appleStock,oakStock=BrandyDistiller.oakStock,spiceStock=BrandyDistiller.spiceStock,fuelStock=BrandyDistiller.fuelStock,silverStock=BrandyDistiller.silverStock,goldStock=BrandyDistiller.goldStock,jewelStock=BrandyDistiller.jewelStock,productStock=BrandyDistiller.productStock,numBuildings=#BrandyDistiller.buildings,hasMaker=BrandyDistiller.maker~=nil,makerName=BrandyDistiller.maker and BrandyDistiller.maker.name or "—",makerSkill=BrandyDistiller.maker and BrandyDistiller.maker.skill or 0,activeMaking=#BrandyDistiller.activeMaking,totalProducts=BrandyDistiller.totalProducts} end
return BrandyDistiller
